+                Model.InsuranceProvider,
+                Model.Doctor,
+                Model.TimeSlot);
+
+            if (errors.Count > 0)
+            {
+                serverErrors = errors;
+            }
+            else
+            {
+                availabilityConfirmed = true;
+            }
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+
